/*
 * WhatsApp Business publication is PROVIDER-SPECIFIC and, in the research
 * system, only partially implemented and under test. This node therefore
 * fails CLOSED: unless every required configuration value is explicitly
 * present, the branch reports 'not_configured' and nothing is sent.
 *
 * Required in clients.platform_config.whatsapp:
 *   phone_number_id  - the WhatsApp Business phone number id
 *   api_version      - optional, falls back to WHATSAPP_API_VERSION
 *   endpoint         - optional, falls back to graph.facebook.com
 *   recipients       - array of E.164 numbers with recorded opt-in
 *   template         - optional; required for business-initiated messages
 *                      outside the 24h customer service window
 */
const j = $json;
let cfg = {}, creative = {};
try { cfg = typeof j.platform_config === 'string' ? JSON.parse(j.platform_config) : (j.platform_config || {}); } catch (e) { cfg = {}; }
try { creative = typeof j.creative === 'string' ? JSON.parse(j.creative) : (j.creative || {}); } catch (e) { creative = {}; }

const phoneNumberId = cfg.phone_number_id || $env.WHATSAPP_PHONE_NUMBER_ID;
const apiVersion = cfg.api_version || $env.WHATSAPP_API_VERSION || 'v21.0';
const host = cfg.endpoint || 'https://graph.facebook.com';
const recipients = Array.isArray(cfg.recipients) ? cfg.recipients.filter(r => /^\+?[1-9]\d{7,14}$/.test(String(r))) : [];
const body = [String(creative.caption || '').trim(), String(creative.cta || '').trim()].filter(Boolean).join('\n\n').slice(0, 900);

const missing = [];
if (!phoneNumberId) missing.push('phone_number_id');
if (recipients.length === 0) missing.push('recipients_with_opt_in');
if (!body) missing.push('message_body');
if (cfg.opt_in_confirmed !== true) missing.push('opt_in_confirmation_flag');

return {
  json: {
    schedule_id: j.schedule_id,
    asset_id: j.asset_id,
    campaign_id: j.campaign_id,
    client_id: j.client_id,
    platform: 'whatsapp',
    configured: missing.length === 0,
    missing_configuration: missing,
    url: host.replace(/\/$/, '') + '/' + apiVersion + '/' + phoneNumberId + '/messages',
    recipients,
    body,
    image_url: /^https?:\/\//i.test(String(j.storage_ref || '')) ? j.storage_ref : null,
    template: cfg.template || null
  }
};

const prep = $('CODE - WhatsApp Message Preparation').first().json;
const rows = $input.all().map(i => i.json);
const ids = rows.flatMap(r => (r.messages || []).map(m => m.id)).filter(Boolean);
return [{
  json: {
    ...prep,
    status: ids.length > 0 ? 'published' : 'failed',
    platform_post_id: ids[0] || null,
    all_message_ids: ids,
    published_at: new Date().toISOString(),
    raw_response: { responses: rows },
    error_detail: ids.length > 0 ? null : { stage: 'publication', platform: 'whatsapp', error_code: 'no_message_id_returned', message: 'WhatsApp API returned no message id', retry_count: 0, timestamp: new Date().toISOString() }
  }
}];

const prep = $('CODE - WhatsApp Message Preparation').first().json;
const e = $input.first().json || {};
const code = e.error?.error?.code || e.error?.code || e.code || 'whatsapp_api_error';
const msg = e.error?.error?.message || e.error?.message || e.message || 'WhatsApp publication failed';
return [{
  json: {
    ...prep,
    status: 'failed',
    platform_post_id: null,
    published_at: null,
    raw_response: e,
    error_detail: { stage: 'publication', platform: 'whatsapp', error_code: String(code), message: String(msg), retry_count: 2, timestamp: new Date().toISOString() }
  }
}];
